import SwaggerParser from "@apidevtools/swagger-parser";

const file = process.argv[2] ?? "openapi.yaml";

try {
  const api = await SwaggerParser.validate(file);
  const version = api.openapi ?? api.swagger;
  console.log(`${file} is valid (version ${version}, ${Object.keys(api.paths ?? {}).length} paths)`);
} catch (err) {
  console.error(`${file} failed validation:\n${err.message}`);
  process.exitCode = 1;
}
